def isbn_valid(s: str) -> bool:
    t = s.replace('-', '').replace(' ', '')
    if len(t) == 10:
        if not all(c.isdigit() and c.isascii() for c in t[:9]):
            return False
        last = t[9]
        if last == 'X':
            v = 10
        elif last.isdigit() and last.isascii():
            v = int(last)
        else:
            return False
        total = sum((i + 1) * int(c) for i, c in enumerate(t[:9])) + 10 * v
        return total % 11 == 0
    if len(t) == 13:
        if not all(c.isdigit() and c.isascii() for c in t):
            return False
        total = sum(int(c) * (1 if i % 2 == 0 else 3) for i, c in enumerate(t))
        return total % 10 == 0
    return False
```

Hyphens and spaces are stripped first; `isdigit()`/`isascii()` together reject non-ASCII digit characters, and lowercase `'x'` fails the check since only the exact character `'X'` is accepted.
